package com.musteritakipcrm.alarm;

import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.text.InputType;import android.view.*;import android.widget.*;import java.text.SimpleDateFormat;import java.util.*;

public class MainActivity extends Activity{
 private static final String PREF="crm_alarm"; private LinearLayout list; private boolean archive=false;
 private final int[] CARD_COLORS={Color.rgb(255,248,196),Color.rgb(225,245,254),Color.rgb(232,245,233),Color.rgb(255,235,238),Color.rgb(243,229,245),Color.rgb(255,243,224)};
 @Override public void onCreate(Bundle b){super.onCreate(b);AlarmRingingService.ensureChannels(this);requestPermissionsIfNeeded();setContentView(ui());if(token().isEmpty())pairDialog();else{startServiceNow();load();}}
 private LinearLayout ui(){LinearLayout root=v();root.setBackgroundColor(Color.rgb(240,247,252));TextView h=t("📝  AJANDAM",22,true);h.setPadding(22,18,22,18);h.setBackgroundColor(Color.rgb(255,202,40));root.addView(h,new LinearLayout.LayoutParams(-1,-2));LinearLayout body=v();body.setPadding(14,10,14,12);root.addView(body,new LinearLayout.LayoutParams(-1,-1));Button add=new Button(this);add.setText("+ YENİ NOT");add.setTextSize(15);add.setOnClickListener(x->{if(connected())newNote();});body.addView(add);LinearLayout tabs=new LinearLayout(this);Button notes=new Button(this);notes.setText("NOTLAR");notes.setTextSize(14);Button ar=new Button(this);ar.setText("ARŞİV");ar.setTextSize(14);notes.setOnClickListener(x->{archive=false;if(connected())load();});ar.setOnClickListener(x->{archive=true;if(connected())load();});tabs.addView(notes,new LinearLayout.LayoutParams(0,-2,1));tabs.addView(ar,new LinearLayout.LayoutParams(0,-2,1));body.addView(tabs);ScrollView sc=new ScrollView(this);list=v();sc.addView(list);body.addView(sc,new LinearLayout.LayoutParams(-1,0,1));return root;}
 private boolean connected(){if(!token().isEmpty())return true;pairDialog();return false;}
 private void pairDialog(){list.removeAllViews();list.addView(t("Site ajandanızla senkronize etmek için bir kez bağlantı yapın.",16,true));Button b=new Button(this);b.setText("SİTEYE BAĞLAN");b.setOnClickListener(v->showCodeDialog());list.addView(b);}
 private void showCodeDialog(){EditText code=new EditText(this);code.setHint("6 haneli bağlantı kodu");code.setInputType(InputType.TYPE_CLASS_NUMBER);code.setTextSize(22);code.setGravity(Gravity.CENTER);AlertDialog d=new AlertDialog.Builder(this).setTitle("AJANDAM'ı Bağla").setMessage("Sitedeki 6 haneli bağlantı kodunu girin.").setView(code).setNegativeButton("VAZGEÇ",null).setPositiveButton("BAĞLA",null).create();d.setOnShowListener(x->d.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String c=code.getText().toString().trim();if(c.length()!=6){show("6 haneli kodu girin.");return;}new Thread(()->{try{String tok=Api.pair(c,"AJANDAM");getSharedPreferences(PREF,MODE_PRIVATE).edit().putString("token",tok).apply();runOnUiThread(()->{d.dismiss();startServiceNow();load();});}catch(Exception e){runOnUiThread(()->show("Bağlantı olmadı: "+e.getMessage()));}}).start();}));d.show();}
 private void load(){String tok=token();if(tok.isEmpty()){pairDialog();return;}list.removeAllViews();new Thread(()->{try{List<Api.Entry> all=Api.agenda(tok);runOnUiThread(()->render(all));}catch(Exception e){runOnUiThread(()->show("Ajanda alınamadı: "+e.getMessage()));}}).start();}
 private String titleOf(String note){int p=note.indexOf('\n');return (p<0?note:note.substring(0,p)).trim();}
 private String detailOf(String note){int p=note.indexOf('\n');return p<0?"":note.substring(p+1).trim();}
 private void render(List<Api.Entry> all){list.removeAllViews();int n=0;for(Api.Entry e:all){if(e.archived()!=archive)continue;int idx=n++;LinearLayout card=v();card.setPadding(13,6,13,6);GradientDrawable bg=new GradientDrawable();bg.setColor(CARD_COLORS[idx%CARD_COLORS.length]);bg.setCornerRadius(16);bg.setStroke(2,Color.rgb(90,145,190));card.setBackground(bg);TextView title=t(titleOf(e.note),16,true);title.setPadding(5,3,5,1);card.addView(title);String detail=detailOf(e.note);if(!detail.isEmpty()){TextView desc=t(detail,14,false);desc.setPadding(5,1,5,2);desc.setTextColor(Color.rgb(55,55,55));card.addView(desc);}String meta="📅 "+e.date;if(!e.remindAt.isEmpty())meta+="   ⏰ "+e.remindAt.replace(e.date,"").trim();TextView m=t(meta,12,false);m.setPadding(5,2,5,2);m.setTextColor(Color.rgb(95,95,95));card.addView(m);card.setClickable(true);card.setOnClickListener(x->actionMenu(e));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,2,0,2);list.addView(card,p);}if(n==0)list.addView(t(archive?"Arşiv boş.":"Henüz not yok.",15,false));}
 private void actionMenu(Api.Entry e){String archiveText=e.archived()?"↩ ARŞİVDEN ÇIKAR":"📦 ARŞİV";String alarmText=e.remindAt.isEmpty()?"⏰ ALARM EKLE":"⏰ ALARMI DEĞİŞTİR";String[] a={"✏ DÜZENLE",alarmText,archiveText,"🗑 SİL"};new AlertDialog.Builder(this).setTitle(titleOf(e.note)).setItems(a,(d,w)->{if(w==0)editForm(e,false);else if(w==1)editForm(e,true);else if(w==2)archive(e,!e.archived());else delete(e);}).setNegativeButton("KAPAT",null).show();}
 private void newNote(){editForm(null,false);}
 private void editForm(Api.Entry e,boolean alarmOnly){LinearLayout form=v();form.setPadding(28,6,28,0);EditText title=new EditText(this);title.setHint("Başlık");title.setTextSize(16);title.setSingleLine(true);title.setText(e==null?"":titleOf(e.note));form.addView(title);EditText detail=new EditText(this);detail.setHint("Açıklama");detail.setTextSize(14);detail.setMinLines(2);detail.setText(e==null?"":detailOf(e.note));form.addView(detail);Button date=new Button(this);Button time=new Button(this);date.setTextSize(13);time.setTextSize(13);form.addView(date);form.addView(time);final Calendar c=Calendar.getInstance();if(e!=null&&!e.date.isEmpty()){try{c.setTime(new SimpleDateFormat("yyyy-MM-dd",Locale.US).parse(e.date));}catch(Exception ignored){}}final boolean[] hasTime={e!=null&&!e.remindAt.isEmpty()};final String[] day={fmt(c,"yyyy-MM-dd")};if(hasTime[0]){try{String[] q=e.remindAt.split(" ");if(q.length>1){String[] hm=q[1].split(":");c.set(Calendar.HOUR_OF_DAY,Integer.parseInt(hm[0]));c.set(Calendar.MINUTE,Integer.parseInt(hm[1]));}}catch(Exception ignored){}}date.setText("📅 "+fmt(c,"dd.MM.yyyy"));time.setText(hasTime[0]?String.format(Locale.getDefault(),"⏰ %02d:%02d",c.get(Calendar.HOUR_OF_DAY),c.get(Calendar.MINUTE)):"⏰ Alarm yok");date.setOnClickListener(v->new DatePickerDialog(this,(d,y,m,dd)->{c.set(y,m,dd);day[0]=fmt(c,"yyyy-MM-dd");date.setText("📅 "+fmt(c,"dd.MM.yyyy"));},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH)).show());time.setOnClickListener(v->new TimePickerDialog(this,(d,h,min)->{c.set(Calendar.HOUR_OF_DAY,h);c.set(Calendar.MINUTE,min);hasTime[0]=true;time.setText(String.format(Locale.getDefault(),"⏰ %02d:%02d",h,min));},c.get(Calendar.HOUR_OF_DAY),c.get(Calendar.MINUTE),true).show());AlertDialog dlg=new AlertDialog.Builder(this).setTitle(e==null?"Yeni Not":(alarmOnly?"Alarm":"Düzenle")).setView(form).setNegativeButton("VAZGEÇ",null).setPositiveButton("KAYDET",null).create();dlg.setOnShowListener(x->dlg.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String baslik=title.getText().toString().trim();String aciklama=detail.getText().toString().trim();if(baslik.isEmpty()){show("Başlık boş olamaz.");return;}String note=baslik+(aciklama.isEmpty()?"":"\n"+aciklama);String rem=hasTime[0]?day[0]+String.format(Locale.US," %02d:%02d",c.get(Calendar.HOUR_OF_DAY),c.get(Calendar.MINUTE)):"";dlg.dismiss();if(e==null)save(day[0],note,rem);else update(e.id,day[0],note,rem);}));dlg.show();}
 private void save(String d,String n,String r){new Thread(()->{try{Api.addEntry(token(),d,n,r);runOnUiThread(()->{show("Kaydedildi");load();});}catch(Exception e){runOnUiThread(()->show("Kaydedilemedi: "+e.getMessage()));}}).start();}
 private void update(int id,String d,String n,String r){new Thread(()->{try{Api.updateEntry(token(),id,d,n,r);runOnUiThread(()->{show("Güncellendi");load();});}catch(Exception e){runOnUiThread(()->show("Güncellenemedi: "+e.getMessage()));}}).start();}
 private void archive(Api.Entry e,boolean a){new Thread(()->{try{Api.archive(token(),e.id,a);runOnUiThread(this::load);}catch(Exception x){runOnUiThread(()->show(x.getMessage()));}}).start();}
 private void delete(Api.Entry e){new AlertDialog.Builder(this).setTitle("Notu Sil").setMessage("Bu not silinsin mi?").setNegativeButton("HAYIR",null).setPositiveButton("SİL",(d,w)->new Thread(()->{try{Api.deleteEntry(token(),e.id);runOnUiThread(this::load);}catch(Exception x){runOnUiThread(()->show(x.getMessage()));}}).start()).show();}
 private void show(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();} private String token(){return getSharedPreferences(PREF,MODE_PRIVATE).getString("token","");}
 private LinearLayout v(){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);return x;} private TextView t(String s,int z,boolean b){TextView x=new TextView(this);x.setText(s);x.setTextSize(z);x.setTextColor(Color.BLACK);if(b)x.setTypeface(null,Typeface.BOLD);return x;} private String fmt(Calendar c,String p){return new SimpleDateFormat(p,Locale.US).format(c.getTime());}
 private void startServiceNow(){Intent i=new Intent(this,SyncService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);} private void requestPermissionsIfNeeded(){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},20);}
}
